    "description": "चक्र फूल (स्टार ऐनीज़) मसाला-प्रकार की एक प्रमुख फसल के रूप में जानी जाती है जिसका व्यापक कृषि महत्व है। यह 20-30°C तापमान और मध्यम वर्षा वाली नमी में सबसे अच्छी तरह से विकसित होता है। यह सफल अच्छी जल विक्रेताओं वाली डोमट मिट्टी। में विशेष रूप से अच्छा प्रदर्शन करता है। स्वस्थ उपजी सुरक्षा के लिए, किसानों को लीफ स्पॉट और रूट रोट जैसे खतरों का सक्रिय रूप से प्रबंधन करना चाहिए। सर्वोत्तम बाजार मूल्य प्राप्त करने के लिए सही उपभोक्ता स्तर पर समय की कटौती महत्वपूर्ण है।",
